  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  let invoice = issueInvoice(inv.value, []).value;
  const payment = recordPayment(invoice, { amount: 50000, date: '2026-10-08' });
  assert.equal(payment.ok, true);
  invoice = payment.value;

  const result = statement('C-002', [invoice], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].due, 64950);
});

test('statement returns invoice with number, issueDate, dueDate, total, due', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = statement('C-002', [issued.value], '2026-10-07');
  assert.equal(result.ok, true);
  const inv_statement = result.value.invoices[0];
  assert.equal(typeof inv_statement.number, 'string');
  assert.equal(typeof inv_statement.issueDate, 'string');
  assert.equal(typeof inv_statement.dueDate, 'string');
  assert.equal(typeof inv_statement.total, 'number');
  assert.equal(typeof inv_statement.due, 'number');
});

test('statement calculates totalDue as sum of due amounts', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  assert.equal(issued2.ok, true);

  const result = statement('C-002', [issued1.value, issued2.value], '2026-10-07');
  assert.equal(result.ok, true);
  // first invoice: 10 * 9500 + 21% vat = 114950
  // second invoice: 5 * 9500 + 21% vat = 57475
  // total: 114950 + 57475 = 172425
  assert.equal(result.value.totalDue, 172425);
});

test('statement excludes other customers invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  assert.equal(issued2.ok, true);

  const result = statement('C-002', [issued1.value, issued2.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
});

test('statement with partially paid invoice has non-zero due', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  let invoice = issueInvoice(inv.value, []).value;
  const payment = recordPayment(invoice, { amount: 30000, date: '2026-10-08' });
  assert.equal(payment.ok, true);
  invoice = payment.value;

  const result = statement('C-002', [invoice], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].due, 84950);
  assert.equal(result.value.totalDue, 84950);
});

test('statement with voucher reflects reduced due', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  let invoice = applyVoucher(inv.value, { code: 'SAVE10', amount: 10000 }).value;
  invoice = issueInvoice(invoice, []).value;

  const result = statement('C-002', [invoice], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].due, 104950);
});

