test('statement sorts invoices by issueDate', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(inv3.ok, true);
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const result = statement('C-002', [issued1.value, issued2.value, issued3.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-05');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-08');
  assert.equal(result.value.invoices[2].issueDate, '2026-10-10');
});

